function gfSettingSet(string $key,string $value):void{try{$stmt=db()->prepare('INSERT INTO app_settings(setting_key,setting_value,updated_at,updated_by) VALUES(:k,:v,NOW(),:u) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_at=NOW(),updated_by=VALUES(updated_by)');$stmt->execute([':k'=>$key,':v'=>$value,':u'=>'gf-ai-generate']);}catch(Throwable $e){}}
