function gfRunJob(int $jobId,array $payload):void{try{ignore_user_abort(true);@set_time_limit(0);if(session_status()===PHP_SESSION_ACTIVE){session_write_close();}gfJobUpdate($jobId,'running',2,'Falldaten und Quellen werden geladen.');$folderId=trim((string)($payload['folder_id']??''));$order=is_array($payload['order']??null)?$payload['order']:[];$outputs=array_values(array_filter(array_map('strval',is_array($order['outputs']??null)?$order['outputs']:[])));$allowed=['dokumentenindex','rechnungsregister','erstbericht','schadenprotokoll','schlusserklaerung','zahlungsbefuerwortung','nachtrag_stellungnahme','zwischenbericht','schlussbericht','vorauszahlung','query_form'];if($folderId===''||!$outputs)throw new RuntimeException('Fall oder Dokumentauswahl fehlt.');foreach($outputs as$o)if(!in_array($o,$allowed,true))throw new RuntimeException('Unbekannter Dokumenttyp: '.$o);$meta=gfReadJson($folderId,GF_CASE_META);if(!$meta)throw new RuntimeException('Falldaten konnten nicht geladen werden.');$instructions=trim((string)($order['instructions']??''));if($instructions==='')throw new RuntimeException('Arbeitsauftrag fehlt.');$caseFiles=gfCaseFiles($folderId);if(!$caseFiles)throw new RuntimeException('Im aktiven Fall wurden keine auswertbaren Unterlagen gefunden.');$knowledgeFiles=gfKnowledgeFiles();if(!$knowledgeFiles)throw new RuntimeException('Keine Engel/QS-/GF-Regelwerke in der Google-Drive-Wissensbasis gefunden.');gfJobUpdate($jobId,'running',8,'Fallunterlagen werden für die KI vorbereitet.');$caseRefs=[];foreach($caseFiles as$f){$r=gfOpenAIUploadDriveFile($f,'case');if($r)$caseRefs[]=$r;}if(!$caseRefs)throw new RuntimeException('Fallunterlagen konnten der KI nicht bereitgestellt werden.');gfJobUpdate($jobId,'running',18,'Regelwerke werden geladen.');$ruleRefs=[];foreach($knowledgeFiles as$f){$r=gfOpenAIUploadDriveFile($f,'knowledge');if($r)$ruleRefs[]=$r;}if(!$ruleRefs)throw new RuntimeException('Regelwerke konnten der KI nicht bereitgestellt werden.');$bkiRequested=preg_